//! Passive Text children preserve native identity, records and live ranges.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><noscript id=host>held</noscript><button id=button><noscript id=guard>guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-text-move-before.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,code:&str)->String{let source=format!("var caughtFailure=null;try{{{code}}}catch(e){{caughtFailure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let value=p.runtime.execute("caughtFailure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();let Value::String(message)=value else{panic!("Expected an actual native refusal: {value:?}")};message}}}


#[test]
fn noscript_text_move_before_actual_passive_and_ordinary_transfers_records_ranges_and_iterator(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var first=document.getElementById('host'),text=first.firstChild,raw='A\udfff\ud800B';text.data=raw;var second=first.cloneNode(false);second.textContent='end';document.body.appendChild(second);var end=second.firstChild,out=document.getElementById('out'),range=document.createRange(),watch=new MutationObserver(function(){}),iterator=document.createNodeIterator(document.body,NodeFilter.SHOW_ALL);range.setStart(text,1);range.setEnd(text,3);while(iterator.nextNode()!==text){}watch.observe(first,{childList:true});watch.observe(second,{childList:true});watch.observe(out,{childList:true});if(second.moveBefore(text,end)!==undefined)throw 'move return';var rs=watch.takeRecords();if(first.firstChild!==null||second.firstChild!==text||text.nextSibling!==end||text.parentNode!==second||text.ownerDocument!==document||!text.isConnected||text.data!==raw||rs.length!==2||rs[0].target!==first||rs[0].removedNodes[0]!==text||rs[1].target!==second||rs[1].addedNodes[0]!==text||rs[1].previousSibling!==null||rs[1].nextSibling!==end||range.startContainer!==first||range.endContainer!==first||range.startOffset||range.endOffset||iterator.referenceNode!==first)throw 'actual passive Text move';out.moveBefore(text,null);rs=watch.takeRecords();if(second.firstChild!==end||out.lastChild!==text||text.data!==raw||rs.length!==2||rs[0].target!==second||rs[0].removedNodes[0]!==text||rs[1].target!==out||rs[1].addedNodes[0]!==text)throw 'passive to ordinary move';first.moveBefore(text,null);rs=watch.takeRecords();if(first.firstChild!==text||out.textContent!=='Real'||rs.length!==2||rs[0].target!==out||rs[1].target!==first||rs[1].addedNodes[0]!==text||text.data!==raw)throw 'ordinary to passive move';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_text_move_before_same_parent_self_reference_and_actual_sibling_records(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),a=document.createTextNode('a'),b=document.createTextNode('b'),c=document.createTextNode('c'),watch=new MutationObserver(function(){});host.replaceChildren(a,b,c);watch.observe(host,{childList:true});host.moveBefore(c,a);var rs=watch.takeRecords();if(host.firstChild!==c||c.nextSibling!==a||a.nextSibling!==b||host.lastChild!==b||rs.length!==2||rs[0].removedNodes[0]!==c||rs[0].previousSibling!==b||rs[0].nextSibling!==null||rs[1].addedNodes[0]!==c||rs[1].previousSibling!==null||rs[1].nextSibling!==a)throw 'actual same-parent Text move';host.moveBefore(c,c);rs=watch.takeRecords();if(host.firstChild!==c||c.nextSibling!==a||rs.length!==2||rs[0].removedNodes[0]!==c||rs[1].addedNodes[0]!==c)throw 'self reference adjustment retains move records';host.moveBefore(a,undefined);rs=watch.takeRecords();if(c.nextSibling!==b||b.nextSibling!==a||host.lastChild!==a||rs.length!==2||rs[0].removedNodes[0]!==a||rs[1].addedNodes[0]!==a)throw 'explicit undefined move reference';"#);assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_text_move_before_native_nontext_root_and_membership_guards_are_atomic(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),text=host.firstChild,guarded=document.getElementById('guard'),blocked=guarded.firstChild,out=document.getElementById('out'),span=document.createElement('span'),fresh=document.createTextNode('fresh'),watch=new MutationObserver(function(){});out.appendChild(span);watch.observe(document.body,{childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;
 for(code,category)in[("host.moveBefore(span,null);","inert resource subtrees"),("host.moveBefore(blocked,null);","inert resource subtrees"),("guarded.moveBefore(text,null);","inert resource subtrees"),("host.moveBefore(text,span);","NotFoundError"),("host.moveBefore(fresh,null);","HierarchyRequestError")]{p.begin_job();let e=refusal(&mut d,&mut f,&mut p,code);assert!(e.contains(category),"{code}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==text||guarded.firstChild!==blocked||span.parentNode!==out||fresh.parentNode!==null||watch.takeRecords().length)throw 'moveBefore guarded prefix';");}p.begin_job();run(&mut d,&mut f,&mut p,"document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_text_move_before_copy_work_retained_refusals_preserve_state_and_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var owner=document.implementation.createHTMLDocument('owner'),donor=owner.createElement('noscript');for(var i=0;i<128;i++)donor.appendChild(owner.createTextNode('x'));var host=document.importNode(donor,true);document.body.appendChild(host);var out=document.getElementById('out'),text=out.firstChild,range=document.createRange(),watch=new MutationObserver(function(){});range.setStart(text,1);range.setEnd(text,2);watch.observe(out,{childList:true});watch.observe(host,{childList:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;
 for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.retained_limit=p.state.retained};let e=refusal(&mut d,&mut f,&mut p,"host.moveBefore(text,null);").to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),_=>e.contains("allowance")||e.contains("retained")||e.contains("storage")},"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.childNodes.length!==128||text.parentNode!==out||out.firstChild!==text||text.data!=='Real'||range.startContainer!==text||range.endContainer!==text||range.startOffset!==1||range.endOffset!==2||watch.takeRecords().length)throw 'moveBefore quota atomic';");}p.begin_job();run(&mut d,&mut f,&mut p,"host.moveBefore(text,null);var rs=watch.takeRecords();if(host.childNodes.length!==129||host.lastChild!==text||out.firstChild!==null||text.data!=='Real'||rs.length!==2||rs[0].target!==out||rs[0].removedNodes[0]!==text||rs[1].target!==host||rs[1].addedNodes[0]!==text||range.startContainer!==out||range.endContainer!==out||range.startOffset||range.endOffset)throw 'fresh passive moveBefore recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
